                                          ^", "query": "SELECT date_trunc('minute', time) minute, count(*) n_slow, round(avg(duration)/1e6,1) avg_ms, sum(CASE WHEN attr_http_response_status_code>=500 THEN 1 ELSE 0 END) e5xx FROM abnormal_traces WHERE service_name IN ('ts-seat-service','ts-travel-service','ts-route-plan-service','ts-travel-plan-service') AND duration > 1000000000 GROUP BY 1 ORDER BY 1", "available_tables": ["abnormal_traces"]}

{"error": "Query execution failed: Binder Error: Ambiguous reference to column name "src" (use: "c.src" or "p.src")

LINE 1: SELECT src, p.service_name parent_svc, p.span_name parent_span...
               ^", "query": "SELECT src, p.service_name parent_svc, p.span_name parent_span, p.attr_span_kind pkind, c.service_name child_svc, c.span_name child_span, count(*) n, round(avg(c.duration)/1e6,1) child_ms FROM (SELECT 'norm' src, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) c JOIN (SELECT 'norm' src, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) p ON c.parent_span_id = p.span_id AND c.src=p.src AND c.trace_id=p.trace_id WHERE p.service_name IN ('ts-seat-service','ts-travel-service') AND p.attr_span_kind='Client' GROUP BY 1,2,3,4,5,6 ORDER BY 1,2,3,7 DESC LIMIT 40", "available_tables": ["normal_traces", "abnormal_traces"]}

